# device.py（モジュール）
class Device:
    def __init__(self, hostname, ip):
        self.hostname = hostname
        self.ip = ip

    def describe(self):
        return f"{self.hostname} ({self.ip})"


def make_devices(rows):
    return [Device(r["hostname"], r["ip"]) for r in rows]

